import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const OUT = path.join(ROOT, "output", "pharmacy-blueprint", "business-intelligence.json");

function svc(name, category, description, benefits, problems, intent) {
  return { serviceKey: name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""), serviceName: name, category, description, customerBenefits: benefits, commonProblemsSolved: problems, customerIntent: intent };
}

